  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function splitDocuments(lines) {
  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') {
      parts.push([])
    } else {
      parts[parts.length - 1].push(line)
    }
  }
  return parts
}

function renderMerge(regions, withBase) {
  const out = []
  let conflicted = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflicted = true
      out.push('<<<<<<< mine')
      out.push(...region.mine)
      if (withBase) {
        out.push('||||||| base')
        out.push(...region.base)
      }
      out.push('=======')
      out.push(...region.theirs)
      out.push('>>>>>>> theirs')
    } else {
      out.push(...region.lines)
    }
  }
  return { text: out.length > 0 ? `${out.join('\n')}\n` : '', conflicted }
}

function renderRegions(regions) {
  const out = []
  let conflicted = false
  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflicted = true
      out.push(`conflict mine=${region.mine.length} base=${region.base.length} theirs=${region.theirs.length}`)
    } else {
      out.push(`${region.kind} ${region.lines.length}`)
    }
  }
  return { text: out.length > 0 ? `${out.join('\n')}\n` : '', conflicted }
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || !MODES.has(args[0])) {
    fail('usage: cli.js merge|merge2|regions')
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  const parts = splitDocuments(splitLines(input))
  if (parts.length !== 3) {
    fail('expected three parts separated by %%%')
  }
  const [mine, base, theirs] = parts

  const regions = buildRegions(mine, base, theirs)

  const { text, conflicted } =
    mode === 'regions' ? renderRegions(regions) : renderMerge(regions, mode === 'merge')

  process.stdout.write(text)
  process.exit(conflicted ? 1 : 0)
}

main()
"}

