 * Parses the election description read from standard input into a list of
 * candidate names and a list of ballots, or throws a ParseError describing
 * the first line that fails to make sense.
 */

const NAME_RE = /^[A-Za-z0-9_-]+$/
const COUNT_RE = /^[1-9]\d*$/

export class ParseError extends Error {
  constructor(message, line = null) {
    super(message)
    this.line = line
  }
}

function fail(line, message) {
  throw new ParseError(message, line)
}

/**
 * @param {string} input the raw standard-input text
 * @returns {{ candidates: string[], ballots: { count: number, names: string[] }[] }}
 */
export function parseElection(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  let candidates = null
  const candidateSet = new Set()
  const ballots = []

  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    const trimmed = lines[i].trim()
    if (trimmed === '' || trimmed.startsWith('#')) continue

    const tokens = trimmed.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidates !== null) {
        fail(lineNumber, 'candidates must be declared once, before any ballot')
      }
      const names = tokens.slice(1)
      if (names.length === 0) {
        fail(lineNumber, 'expected candidates <name>...')
      }
      for (const name of names) {
        if (!NAME_RE.test(name)) {
          fail(lineNumber, `invalid candidate name ${name}`)
        }
        if (candidateSet.has(name)) {
          fail(lineNumber, `candidate ${name} is declared twice`)
        }
        candidateSet.add(name)
      }
      candidates = names
    } else if (directive === 'ballot') {
      if (candidates === null) {
        fail(lineNumber, 'candidates must be declared once, before any ballot')
      }
      const rest = tokens.slice(1)
      if (rest.length < 2) {
        fail(lineNumber, 'expected ballot <count> <candidate>...')
      }
      const countStr = rest[0]
      if (!COUNT_RE.test(countStr)) {
        fail(lineNumber, 'count must be a positive integer')
      }
      const count = Number(countStr)
      const names = rest.slice(1)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          fail(lineNumber, `unknown candidate ${name}`)
        }
        if (seen.has(name)) {
          fail(lineNumber, `candidate ${name} is repeated`)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      fail(lineNumber, `unknown directive ${directive}`)
    }
  }

  if (candidates === null) {
    fail(null, 'no candidates')
  }

  return { candidates, ballots }
}
"}

