 * The scanner for the small language described in the task prompt. `scan`
 * turns a whole source string into an array of tokens, or throws a
 * `LexError` naming the first problem it finds.
 */

const KEYWORDS = new Set(['let', 'if', 'else', 'while', 'return', 'true', 'false', 'null'])

const TWO_CHAR_PUNCT = new Set(['==', '!=', '<=', '>=', '&&', '||', '->', '=>'])
const ONE_CHAR_PUNCT = new Set([
  '+', '-', '*', '/', '%', '=', '<', '>', '!', '(', ')', '{', '}', '[', ']', ',', ';', '.',
])

const isIdentStart = (c) => c !== undefined && /[A-Za-z_]/.test(c)
const isIdentPart = (c) => c !== undefined && /[A-Za-z0-9_]/.test(c)
const isDecDigit = (c) => c !== undefined && /[0-9]/.test(c)
const isHexDigit = (c) => c !== undefined && /[0-9a-fA-F]/.test(c)
const isBinDigit = (c) => c === '0' || c === '1'
const isOctDigit = (c) => c !== undefined && /[0-7]/.test(c)

export class LexError extends Error {
  constructor(line, col, reason) {
    super(`${line}:${col}: ${reason}`)
    this.line = line
    this.col = col
    this.reason = reason
  }
}

function makeState(source) {
  return { chars: Array.from(source), pos: 0, line: 1, col: 1 }
}

function peek(state, offset = 0) {
  return state.chars[state.pos + offset]
}

function advance(state) {
  const c = state.chars[state.pos]
  state.pos++
  if (c === '\n') {
    state.line++
    state.col = 1
  } else if (c === '\t') {
    state.col = Math.floor((state.col - 1) / 4) * 4 + 5
  } else {
    state.col++
  }
  return c
}

function atEnd(state) {
  return state.pos >= state.chars.length
}

function skipTrivia(state) {
  for (;;) {
    const c = peek(state)
    if (c === ' ' || c === '\t' || c === '\r' || c === '\n') {
      advance(state)
      continue
    }
    if (c === '/' && peek(state, 1) === '/') {
      advance(state)
      advance(state)
      while (!atEnd(state) && peek(state) !== '\n') advance(state)
      continue
    }
    if (c === '/' && peek(state, 1) === '*') {
      const openLine = state.line
      const openCol = state.col
      advance(state)
      advance(state)
      let depth = 1
      while (depth > 0) {
        if (atEnd(state)) throw new LexError(openLine, openCol, 'unterminated block comment')
        if (peek(state) === '/' && peek(state, 1) === '*') {
          advance(state)
          advance(state)
          depth++
        } else if (peek(state) === '*' && peek(state, 1) === '/') {
          advance(state)
          advance(state)
          depth--
        } else {
          advance(state)
        }
      }
      continue
    }
    break
  }
}

function scanDigitRun(state, isDigit) {
  let text = ''
  for (;;) {
    const c = peek(state)
    if (isDigit(c)) {
      text += advance(state)
