/**
 * The command. `node src/cli.js tokens` prints every token of the source read
 * from standard input with its position, and `node src/cli.js stats` counts the
 * tokens by kind.
 */

import { readFileSync } from 'node:fs'
import { scan, LexError } from './lexer.js'

const STAT_KINDS = ['ident', 'keyword', 'number', 'punct', 'rawstring', 'string']

function usageError() {
  process.stderr.write('error: usage: cli.js tokens|stats\n')
  process.exit(2)
}

const mode = process.argv[2]
if (process.argv.length !== 3 || (mode !== 'tokens' && mode !== 'stats')) {
  usageError()
}

const source = readFileSync(0, 'utf8')

try {
  const tokens = scan(source)
  let output = ''
  if (mode === 'tokens') {
    for (const token of tokens) {
      output += `${token.line}:${token.col} ${token.kind} ${token.body}\n`
    }
  } else {
    const counts = Object.fromEntries(STAT_KINDS.map((kind) => [kind, 0]))
    for (const token of tokens) counts[token.kind]++
    for (const kind of STAT_KINDS) output += `${kind} ${counts[kind]}\n`
    output += `total ${tokens.length}\n`
  }
  process.stdout.write(output)
  process.exit(0)
} catch (err) {
  if (err instanceof LexError) {
    process.stderr.write(`error: ${err.line}:${err.col}: ${err.reason}\n`)
    process.exit(2)
  }
  throw err
}
"}

