/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { normalizeUri, resolveUri, parseUriReference, UriError } from './uri.js'

function usageFail() {
  process.stderr.write('error: usage: cli.js normalize|resolve\n')
  process.exit(2)
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    usageFail()
    return
  }
  const mode = args[0]

  const input = readFileSync(0, 'utf8')
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const results = []
  for (let i = 0; i < lines.length; i++) {
    const lineNo = i + 1
    const line = lines[i]
    try {
      if (mode === 'normalize') {
        results.push(normalizeUri(line))
      } else {
        const spaceIdx = line.indexOf(' ')
        if (spaceIdx === -1) {
          throw new UriError('expected a base and a reference')
        }
        const base = line.slice(0, spaceIdx)
        const ref = line.slice(spaceIdx + 1)
        const baseParsed = parseUriReference(base)
        if (baseParsed.scheme === undefined) {
          throw new UriError('the base has no scheme')
        }
        results.push(resolveUri(base, ref))
      }
    } catch (err) {
      if (err instanceof UriError) {
        process.stderr.write(`error: line ${lineNo}: ${err.message}\n`)
        process.exit(2)
        return
      }
      throw err
    }
  }

  process.stdout.write(results.map((line) => line + '\n').join(''))
  process.exit(0)
}

main()
"}

