  const chars = Array.from(input)
  const n = chars.length
  let pos = 0
  let line = 1
  let col = 1

  function advance() {
    const c = chars[pos]
    pos++
    if (c === '\n') {
      line++
      col = 1
    } else if (c === '\t') {
      col = (Math.floor((col - 1) / 4) + 1) * 4 + 1
    } else {
      col++
    }
    return c
