      case 'n':
        advance()
        return '\n'
      case 't':
        advance()
        return '\t'
      case 'r':
        advance()
        return '\r'
      case '\\':
        advance()
        return '\\'
      case '"':
        advance()
        return '"'
      case '0':
        advance()
        return '\0'
      case 'x': {
        advance()
