 * Parsing of the election format read by `cli.js` from standard input. See
 * the specification in the task prompt for the exact grammar and the error
 * message text each violation produces.
 */

const NAME_PATTERN = /^[A-Za-z0-9_-]+$/
const COUNT_PATTERN = /^[1-9][0-9]*$/

/** Thrown for any input that fails to parse. `line` is null for errors with no line number. */
export class ParseError extends Error {
  constructor(message, line = null) {
    super(message)
    this.line = line
  }
}

/**
 * Parses an election from raw input text.
 * @returns {{candidates: string[], ballots: {count: number, names: string[]}[]}}
 */
export function parseElection(input) {
  const rawLines = input.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') {
    rawLines.pop()
  }

  const candidates = []
  const candidateSet = new Set()
  const ballots = []
  let candidatesDeclared = false
  let ballotSeen = false

  for (let i = 0; i < rawLines.length; i++) {
    const lineNumber = i + 1
    const line = rawLines[i].trim()
    if (line === '' || line.startsWith('#')) continue

    const tokens = line.split(/\s+/)
    const directive = tokens[0]

    if (directive === 'candidates') {
      if (candidatesDeclared || ballotSeen) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNumber)
      }
      if (tokens.length < 2) {
        throw new ParseError('expected candidates <name>...', lineNumber)
      }
      for (const name of tokens.slice(1)) {
        if (!NAME_PATTERN.test(name)) {
          throw new ParseError(`invalid candidate name ${name}`, lineNumber)
        }
        if (candidateSet.has(name)) {
          throw new ParseError(`candidate ${name} is declared twice`, lineNumber)
        }
        candidateSet.add(name)
        candidates.push(name)
      }
      candidatesDeclared = true
    } else if (directive === 'ballot') {
      if (!candidatesDeclared) {
        throw new ParseError('candidates must be declared once, before any ballot', lineNumber)
      }
      ballotSeen = true
      if (tokens.length < 3) {
        throw new ParseError('expected ballot <count> <candidate>...', lineNumber)
      }
      if (!COUNT_PATTERN.test(tokens[1])) {
        throw new ParseError('count must be a positive integer', lineNumber)
      }
      const count = Number(tokens[1])
      const names = tokens.slice(2)
      const seen = new Set()
      for (const name of names) {
        if (!candidateSet.has(name)) {
          throw new ParseError(`unknown candidate ${name}`, lineNumber)
        }
        if (seen.has(name)) {
          throw new ParseError(`candidate ${name} is repeated`, lineNumber)
        }
        seen.add(name)
      }
      ballots.push({ count, names })
    } else {
      throw new ParseError(`unknown directive ${directive}`, lineNumber)
    }
  }

  if (candidates.length === 0) {
    throw new ParseError('no candidates')
  }

  return { candidates, ballots }
}
"}

