{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-X7yUUY/src/format.js","content":"/**
 * Renders the round-by-round and tally output for `cli.js`.
 */

function formatRoundLine(roundNumber, round) {
  const entries = Object.entries(round.votes).sort(
    ([nameA, votesA], [nameB, votesB]) => votesB - votesA || (nameA < nameB ? -1 : 1)
  )
  const parts = entries.map(([name, count]) => `${name}=${count}`)
  parts.push(`exhausted=${round.exhausted}`)
  return `round ${roundNumber}: ${parts.join(' ')}\n`
}

function formatOutcome(winner) {
  return winner === null ? 'no winner\n' : `winner ${winner}\n`
}

export function formatRounds(rounds, winner) {
  let output = ''
  rounds.forEach((round, index) => {
    output += formatRoundLine(index + 1, round)
    if (round.eliminated !== null) output += `eliminated ${round.eliminated}\n`
  })
  output += formatOutcome(winner)
  return output
}

export function formatTally(rounds, winner) {
  return `rounds ${rounds.length}\n${formatOutcome(winner)}`
}
"}

