{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-aGFjF0/src/parser.js","content":"/**
 * Recursive-descent parser for formula bodies. Produces an AST or throws
 * `FormulaSyntaxError` when the token stream does not match the grammar.
 *
 * Precedence, loosest to tightest: comparisons, `+`/`-`, `*`/`/`, `^`
 * (right-associative), then a leading unary `+`/`-` (tighter than `^`).
 * A range (`A1:B3`) is only accepted directly as a function argument.
 */
import { tokenize, FormulaSyntaxError } from './lexer.js'

const COMPARISON_TYPES = new Set(['EQ', 'NE', 'LT', 'LE', 'GT', 'GE'])
const FUNCTION_NAMES = new Set(['SUM', 'MIN', 'MAX', 'COUNT', 'AVG', 'ABS', 'IF'])

class Parser {
  constructor(tokens) {
    this.tokens = tokens
    this.pos = 0
  }

  peek(offset = 0) {
    return this.tokens[this.pos + offset]
  }

  expect(type) {
    const t = this.peek()
    if (!t || t.type !== type) throw new FormulaSyntaxError(`expected ${type}`)
    this.pos += 1
    return t
  }

  parseComparison() {
    let node = this.parseAdditive()
    while (this.peek() && COMPARISON_TYPES.has(this.peek().type)) {
      const op = this.peek().type
      this.pos += 1
      const right = this.parseAdditive()
      node = { type: 'Binary', op, left: node, right }
    }
    return node
  }

  parseAdditive() {
    let node = this.parseMultiplicative()
    while (this.peek() && (this.peek().type === 'PLUS' || this.peek().type === 'MINUS')) {
      const op = this.peek().type
      this.pos += 1
      const right = this.parseMultiplicative()
      node = { type: 'Binary', op, left: node, right }
    }
    return node
  }

  parseMultiplicative() {
    let node = this.parsePower()
    while (this.peek() && (this.peek().type === 'STAR' || this.peek().type === 'SLASH')) {
      const op = this.peek().type
      this.pos += 1
      const right = this.parsePower()
      node = { type: 'Binary', op, left: node, right }
    }
    return node
  }

  parsePower() {
    const left = this.parseUnary()
    if (this.peek() && this.peek().type === 'CARET') {
      this.pos += 1
      const right = this.parsePower()
      return { type: 'Binary', op: 'CARET', left, right }
    }
    return left
  }

  parseUnary() {
    const t = this.peek()
    if (t && (t.type === 'PLUS' || t.type === 'MINUS')) {
      this.pos += 1
      const operand = this.parseUnary()
      return { type: 'Unary', op: t.type, operand }
    }
    return this.parsePrimary()
  }

  parsePrimary() {
    const t = this.peek()
    if (!t) throw new FormulaSyntaxError('unexpected end of formula')
    if (t.type === 'NUMBER') {
      this.pos += 1
      return { type: 'Number', value: Number(t.text) }
    }
    if (t.type === 'LPAREN') {
      this.pos += 1
      const inner = this.parseComparison()
      this.expect('RPAREN')
      return inner
    }
    if (t.type === 'IDENT') {
      this.pos += 1
      const upper = t.text.toUpperCase()
      if (this.peek() && this.peek().type === 'LPAREN') {
        this.pos += 1
        const args = this.parseArgs()
        this.expect('RPAREN')
        return { type: 'Call', name: upper, args }
      }
      if (upper === 'TRUE') return { type: 'Bool', value: true }
      if (upper === 'FALSE') return { type: 'Bool', value: false }
      return { type: 'Address', name: upper }
    }
    throw new FormulaSyntaxError(`unexpected token ${t.type}`)
  }

  parseArgs() {
    const args = []
    if (this.peek() && this.peek().type === 'RPAREN') return args
    args.push(this.parseArg())
    while (this.peek() && this.peek().type === 'COMMA') {
      this.pos += 1
      args.push(this.parseArg())
    }
    return args
  }

  parseArg() {
    const t0 = this.peek()
    const t1 = this.peek(1)
    const t2 = this.peek(2)
    if (t0 && t0.type === 'IDENT' && t1 && t1.type === 'COLON' && t2 && t2.type === 'IDENT') {
      const save = this.pos
      const start = t0.text.toUpperCase()
      const end = t2.text.toUpperCase()
      this.pos += 3
      const follow = this.peek()
      if (!follow || follow.type === 'COMMA' || follow.type === 'RPAREN') {
        return { type: 'Range', start, end }
      }
      this.pos = save
    }
    return this.parseComparison()
  }
}

/** Parses a formula body (the text after the leading `=`) into an AST. */
export function parseFormula(text) {
  const tokens = tokenize(text)
  const parser = new Parser(tokens)
  if (tokens.length === 0) throw new FormulaSyntaxError('empty formula')
  const node = parser.parseComparison()
  if (parser.pos !== tokens.length) throw new FormulaSyntaxError('trailing tokens')
  return node
}

export { FUNCTION_NAMES }
"}

