      return { type: 'Number', value: Number(t.text) }
    }
    if (t.type === 'LPAREN') {
      this.pos += 1
      const inner = this.parseComparison()
      this.expect('RPAREN')
      return inner
    }
    if (t.type === 'IDENT') {
      this.pos += 1
      const upper = t.text.toUpperCase()
      if (this.peek() && this.peek().type === 'LPAREN') {
        this.pos += 1
        const args = this.parseArgs()
        this.expect('RPAREN')
        return { type: 'Call', name: upper, args }
      }
      if (upper === 'TRUE') return { type: 'Bool', value: true }
      if (upper === 'FALSE') return { type: 'Bool', value: false }
      return { type: 'Address', name: upper }
    }
    throw new FormulaSyntaxError(`unexpected token ${t.type}`)
  }

  parseArgs() {
    const args = []
    if (this.peek() && this.peek().type === 'RPAREN') return args
    args.push(this.parseArg())
    while (this.peek() && this.peek().type === 'COMMA') {
      this.pos += 1
      args.push(this.parseArg())
    }
    return args
  }

  parseArg() {
    const t0 = this.peek()
    const t1 = this.peek(1)
    const t2 = this.peek(2)
    if (t0 && t0.type === 'IDENT' && t1 && t1.type === 'COLON' && t2 && t2.type === 'IDENT') {
      const save = this.pos
      const start = t0.text.toUpperCase()
      const end = t2.text.toUpperCase()
      this.pos += 3
      const follow = this.peek()
      if (!follow || follow.type === 'COMMA' || follow.type === 'RPAREN') {
        return { type: 'Range', start, end }
      }
      this.pos = save
    }
    return this.parseComparison()
  }
}

/** Parses a formula body (the text after the leading `=`) into an AST. */
export function parseFormula(text) {
  const tokens = tokenize(text)
  const parser = new Parser(tokens)
  if (tokens.length === 0) throw new FormulaSyntaxError('empty formula')
  const node = parser.parseComparison()
  if (parser.pos !== tokens.length) throw new FormulaSyntaxError('trailing tokens')
  return node
}

export { FUNCTION_NAMES }
"}

