 * Evaluates a parsed sheet: resolves formulas against declared cells, with
 * memoization and cycle detection.
 */
import { parseAddress, addressFor, lettersToIndex } from './address.js'
import { numVal, errVal, boolVal, toNumber, arithmetic, unaryArithmetic, compare } from './values.js'
import { FUNCTION_NAMES } from './parser.js'

/** Builds an evaluator bound to a parsed sheet (a Map from address to cell record). */
export function createEvaluator(cells) {
  const memo = new Map()
  const state = new Map() // address -> 'in-progress' | 'done'

  function evalCell(addr) {
    if (memo.has(addr)) return memo.get(addr)
    const cell = cells.get(addr)
    if (!cell) {
      const v = numVal(0)
      memo.set(addr, v)
      return v
    }
    if (cell.kind === 'literal') {
      memo.set(addr, cell.value)
      return cell.value
    }
    if (state.get(addr) === 'in-progress') {
      return errVal('#CYCLE!')
    }
    if (cell.parseError) {
      const v = errVal('#ERR!')
      memo.set(addr, v)
      return v
    }
    state.set(addr, 'in-progress')
    const v = evalNode(cell.ast)
    state.set(addr, 'done')
    memo.set(addr, v)
    return v
  }

  function evalAddressRef(name) {
    const parsed = parseAddress(name)
    if (!parsed.valid) return errVal('#REF!')
    return evalCell(addressFor(parsed.col, parsed.row))
  }

  /** Evaluates a range argument to the ordered list of cell values it covers, or a single #REF!. */
  function evalRangeList(node) {
    const start = parseAddress(node.start)
    const end = parseAddress(node.end)
    if (!start.valid || !end.valid) return [errVal('#REF!')]
    const minCol = Math.min(start.col, end.col)
    const maxCol = Math.max(start.col, end.col)
    const minRow = Math.min(start.row, end.row)
    const maxRow = Math.max(start.row, end.row)
    const out = []
    for (let col = minCol; col <= maxCol; col += 1) {
      for (let row = minRow; row <= maxRow; row += 1) {
        out.push(evalCell(addressFor(col, row)))
      }
    }
    return out
  }

  /** Evaluates a direct function argument (range or expression) to a single representative value. */
  function evalArgSingle(node) {
    if (node.type === 'Range') {
      const list = evalRangeList(node)
      return list[0]
    }
    return evalNode(node)
  }

  function evalNode(node) {
    switch (node.type) {
      case 'Number':
        return numVal(node.value)
      case 'Bool':
        return boolVal(node.value)
      case 'Address':
        return evalAddressRef(node.name)
      case 'Unary':
        return unaryArithmetic(node.op, evalNode(node.operand))
      case 'Binary': {
        const left = evalNode(node.left)
        if (node.op === 'EQ' || node.op === 'NE' || node.op === 'LT' || node.op === 'LE' || node.op === 'GT' || node.op === 'GE') {
          const right = evalNode(node.right)
          return compare(node.op, left, right)
        }
        const right = evalNode(node.right)
        return arithmetic(node.op, left, right)
      }
      case 'Call':
        return evalCall(node)
      case 'Range':
        // A range never appears as a bare expression node outside of a
        // function argument position; the parser only produces it there.
        return errVal('#ERR!')
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  function evalCall(node) {
    if (node.name === 'IF') return evalIf(node)
    if (!FUNCTION_NAMES.has(node.name)) return errVal('#NAME?')
    if (node.name === 'ABS') return evalAbs(node)
    return evalAggregate(node)
  }

  function evalIf(node) {
    if (node.args.length !== 3) return errVal('#ERR!')
    const cond = evalArgSingle(node.args[0])
    if (cond.type === 'error') return cond
    let truthy
    if (cond.type === 'bool') {
      truthy = cond.value
    } else {
      const n = toNumber(cond)
      if (n.type === 'error') return n
      truthy = n.value !== 0
    }
    return evalArgSingle(node.args[truthy ? 1 : 2])
  }

  function evalAbs(node) {
    if (node.args.length !== 1) return errVal('#ERR!')
    const val = evalArgSingle(node.args[0])
    if (val.type === 'error') return val
    const n = toNumber(val)
    if (n.type === 'error') return n
    const result = Math.abs(n.value)
    if (!Number.isFinite(result)) return errVal('#DIV/0!')
    return numVal(result)
  }

  function flattenArgs(args) {
    const out = []
    for (const arg of args) {
      if (arg.type === 'Range') {
        out.push(...evalRangeList(arg))
      } else {
        out.push(evalNode(arg))
      }
    }
    return out
  }

  function evalAggregate(node) {
    if (node.args.length < 1) return errVal('#ERR!')
    const values = flattenArgs(node.args)
    if (node.name === 'COUNT') {
      for (const v of values) {
        if (v.type === 'error') return v
      }
      const count = values.filter((v) => v.type === 'number').length
      return numVal(count)
    }
    const numbers = []
    for (const v of values) {
      const n = toNumber(v)
      if (n.type === 'error') return n
      numbers.push(n.value)
    }
    if (node.name === 'SUM') {
      const total = numbers.reduce((a, b) => a + b, 0)
      return finiteOrDiv0(total)
    }
    if (node.name === 'AVG') {
      const total = numbers.reduce((a, b) => a + b, 0)
      return finiteOrDiv0(total / numbers.length)
    }
    if (node.name === 'MIN') {
      return finiteOrDiv0(Math.min(...numbers))
    }
    if (node.name === 'MAX') {
      return finiteOrDiv0(Math.max(...numbers))
    }
    throw new Error(`unhandled aggregate function ${node.name}`)
  }

  function finiteOrDiv0(n) {
    if (!Number.isFinite(n)) return errVal('#DIV/0!')
    return numVal(n)
  }

  return { evalCell }
}

/** Collects the set of in-range addresses a parsed formula names directly, ranges expanded. */
export function collectDeps(ast) {
  const set = new Set()

  function visitRange(node) {
    const start = parseAddress(node.start)
    const end = parseAddress(node.end)
    if (!start.valid || !end.valid) return
    const minCol = Math.min(start.col, end.col)
    const maxCol = Math.max(start.col, end.col)
    const minRow = Math.min(start.row, end.row)
    const maxRow = Math.max(start.row, end.row)
    for (let col = minCol; col <= maxCol; col += 1) {
      for (let row = minRow; row <= maxRow; row += 1) {
        set.add(addressFor(col, row))
      }
    }
  }

  function visit(node) {
    switch (node.type) {
      case 'Number':
      case 'Bool':
        return
      case 'Address': {
        const parsed = parseAddress(node.name)
        if (parsed.valid) set.add(addressFor(parsed.col, parsed.row))
        return
      }
      case 'Unary':
        visit(node.operand)
        return
      case 'Binary':
        visit(node.left)
        visit(node.right)
        return
      case 'Call':
        for (const arg of node.args) {
          if (arg.type === 'Range') visitRange(arg)
          else visit(arg)
        }
        return
      default:
        throw new Error(`unknown node type ${node.type}`)
    }
  }

  visit(ast)
  return [...set].sort((a, b) => {
    const pa = parseAddress(a)
    const pb = parseAddress(b)
    if (pa.col !== pb.col) return pa.col - pb.col
    return pa.row - pb.row
  })
}

// Re-exported for callers that only need column indexing.
export { lettersToIndex }
"}

