{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-ipPFGB/src/parser.js","content":"/**
 * Parses a limiter file into declared policies, routes and events.
 */
import { LimiterError } from './errors.js'

const NAME_RE = /^[A-Za-z0-9_./:-]+$/
const INT_RE = /^(0|[1-9][0-9]*)$/

function parseInt10(token, field, least, line) {
  if (!INT_RE.test(token)) throw new LimiterError(line, `${field} must be an integer of at least ${least}`)
  const value = BigInt(token)
  if (value < BigInt(least)) throw new LimiterError(line, `${field} must be an integer of at least ${least}`)
  return value
}

function checkName(token, kind, line) {
  if (!NAME_RE.test(token)) throw new LimiterError(line, `invalid ${kind} ${token}`)
}

/**
 * Splits standard input into non-empty, non-comment token lists, remembering
 * each one's original line number for error reporting.
 */
function tokenizeLines(text) {
  const rawLines = text.split('\n')
  if (rawLines.length > 0 && rawLines[rawLines.length - 1] === '') rawLines.pop()
  const lines = []
  rawLines.forEach((raw, index) => {
    const trimmed = raw.trim()
    if (trimmed === '' || trimmed.startsWith('#')) return
    lines.push({ line: index + 1, tokens: trimmed.split(/\s+/) })
  })
  return lines
}

/**
 * Parses the whole limiter file, returning the declared policies, routes and
 * the ordered list of events. Throws a `LimiterError` on the first invalid
 * line.
 */
export function parseLimiterFile(text) {
  const policies = new Map()
  const routes = []
  const routeByPrefix = new Map()
  const events = []
  let eventsStarted = false
  let lastTick = null

  for (const { line, tokens } of tokenizeLines(text)) {
    const word = tokens[0]

    if (word === 'bucket' || word === 'window' || word === 'route') {
      if (eventsStarted) throw new LimiterError(line, 'declarations must come before the first event')
    }

    if (word === 'bucket') {
      if (tokens.length !== 5) throw new LimiterError(line, 'expected bucket <name> <capacity> <refill> <per>')
      const [, name, capacityTok, refillTok, perTok] = tokens
      checkName(name, 'policy name', line)
      const capacity = parseInt10(capacityTok, 'capacity', 1, line)
      const refill = parseInt10(refillTok, 'refill', 0, line)
      const per = parseInt10(perTok, 'per', 1, line)
      if (policies.has(name)) throw new LimiterError(line, `policy ${name} is declared twice`)
      policies.set(name, { kind: 'bucket', name, capacity, refill, per })
    } else if (word === 'window') {
      if (tokens.length !== 4) throw new LimiterError(line, 'expected window <name> <limit> <span>')
      const [, name, limitTok, spanTok] = tokens
      checkName(name, 'policy name', line)
      const limit = parseInt10(limitTok, 'limit', 0, line)
      const span = parseInt10(spanTok, 'span', 1, line)
      if (policies.has(name)) throw new LimiterError(line, `policy ${name} is declared twice`)
      policies.set(name, { kind: 'window', name, limit, span })
    } else if (word === 'route') {
      if (tokens.length < 3) throw new LimiterError(line, 'expected route <prefix> <policy>...')
      const prefix = tokens[1]
      const policyNames = tokens.slice(2)
      checkName(prefix, 'route prefix', line)
      for (const policyName of policyNames) {
        if (!policies.has(policyName)) throw new LimiterError(line, `unknown policy ${policyName}`)
      }
      if (routeByPrefix.has(prefix)) throw new LimiterError(line, `prefix ${prefix} is routed twice`)
      const route = { prefix, policyNames }
      routeByPrefix.set(prefix, route)
      routes.push(route)
    } else if (word === 'event') {
      if (tokens.length !== 3) throw new LimiterError(line, 'expected event <tick> <key>')
      const [, tickTok, key] = tokens
      const tick = parseInt10(tickTok, 'tick', 0, line)
      checkName(key, 'key', line)
      if (lastTick !== null && tick < lastTick) throw new LimiterError(line, `tick ${tick} is before tick ${lastTick}`)
      lastTick = tick
      eventsStarted = true
      events.push({ tick, key })
    } else {
      throw new LimiterError(line, `unknown directive ${word}`)
    }
  }

  return { policies, routes, events }
}
"}

