 * Splits raw stdin text into the three documents it holds.
 */

/**
 * Splits `text` on newlines, drops the empty tail a trailing newline
 * leaves, and groups the resulting lines into parts separated by lines
 * that are exactly `%%%`. Throws when the result is not exactly three
 * parts.
 */
export function parseInput(text) {
  const lines = text.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()

  const parts = [[]]
  for (const line of lines) {
    if (line === '%%%') parts.push([])
    else parts[parts.length - 1].push(line)
  }

  if (parts.length !== 3) throw new Error('expected three parts separated by %%%')
  return parts
}
"}

{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-nDp0GM/src/lcs.js","content":"/**
 * Longest common subsequence over whole lines, with the tie-break the
 * task specifies: among equally long subsequences, the one whose
 * matches come earliest.
 */

/**
 * Returns the matching pairs `[baseIndex, sideIndex]`, in increasing
 * order, of an LCS between `base` and `side`. Suffix lengths are
 * computed once, then the match is walked from the start: equal lines
 * are always taken, and otherwise the side whose remaining subsequence
 * (after dropping its current line) stays at least as long is
 * advanced, base preferred on a tie.
 */
export function computeMatches(base, side) {
  const m = base.length
  const n = side.length
  const stride = n + 1
  const suffixLcs = new Int32Array((m + 1) * stride)

  for (let i = m - 1; i >= 0; i--) {
    for (let j = n - 1; j >= 0; j--) {
      const here = i * stride + j
      if (base[i] === side[j]) {
        suffixLcs[here] = suffixLcs[here + stride + 1] + 1
      } else {
        const dropBase = suffixLcs[here + stride]
        const dropSide = suffixLcs[here + 1]
        suffixLcs[here] = dropBase > dropSide ? dropBase : dropSide
      }
    }
  }

  const matches = []
  let i = 0
  let j = 0
  while (i < m && j < n) {
    if (base[i] === side[j]) {
      matches.push([i, j])
      i++
      j++
      continue
    }
