/**
 * Turns the matches between `base` and `side` into the changes that
 * fill the gaps the matches leave: runs of base lines replaced by runs
 * of `side`'s lines, tagged with `side` ('mine' or 'theirs').
 */
function computeChanges(base, side, matches, tag) {
  const changes = []
  let prevBase = 0
  let prevSide = 0
  for (const [baseIndex, sideIndex] of matches) {
    if (baseIndex > prevBase || sideIndex > prevSide) {
      changes.push({
        side: tag,
        baseStart: prevBase,
        baseEnd: baseIndex,
        lines: side.slice(prevSide, sideIndex),
      })
    }
    prevBase = baseIndex + 1
    prevSide = sideIndex + 1
  }
  if (prevBase < base.length || prevSide < side.length) {
    changes.push({
      side: tag,
      baseStart: prevBase,
      baseEnd: base.length,
      lines: side.slice(prevSide, side.length),
    })
  }
  return changes
}

/**
 * Merges mine's and theirs's changes into one list ordered by base
 * start, mine before theirs on a tie.
 */
function mergeChangeLists(mineChanges, theirsChanges) {
  const all = [...mineChanges, ...theirsChanges]
  all.sort((a, b) => {
    if (a.baseStart !== b.baseStart) return a.baseStart - b.baseStart
    if (a.side === b.side) return 0
    return a.side === 'mine' ? -1 : 1
  })
  return all
}

/**
 * Groups the ordered changes into regions: stable stretches of base
 * lines no change touches, and changed regions that absorb every
 * change starting at or before the region's current base end.
 */
function buildRegions(base, allChanges) {
  const regions = []
  let pos = 0
  let index = 0
  while (index < allChanges.length) {
    const first = allChanges[index]
    if (first.baseStart > pos) {
      regions.push({ kind: 'stable', baseStart: pos, baseEnd: first.baseStart })
    }
    const group = [first]
    let regionEnd = first.baseEnd
    index++
    while (index < allChanges.length && allChanges[index].baseStart <= regionEnd) {
      group.push(allChanges[index])
      if (allChanges[index].baseEnd > regionEnd) regionEnd = allChanges[index].baseEnd
      index++
    }
    regions.push({ kind: 'changed', baseStart: first.baseStart, baseEnd: regionEnd, changes: group })
    pos = regionEnd
  }
  if (pos < base.length) {
    regions.push({ kind: 'stable', baseStart: pos, baseEnd: base.length })
  }
  return regions
}

/**
 * Builds one side's lines for a region: its own changes' lines, with
 * the base lines used to pad the parts of the region that side's
 * changes don't cover.
 */
function buildSideLines(base, region, sideChanges) {
  const lines = []
  let pos = region.baseStart
  for (const change of sideChanges) {
    if (change.baseStart > pos) lines.push(...base.slice(pos, change.baseStart))
    lines.push(...change.lines)
    pos = change.baseEnd
  }
  if (pos < region.baseEnd) lines.push(...base.slice(pos, region.baseEnd))
  return lines
}

function arraysEqual(a, b) {
  if (a.length !== b.length) return false
  for (let i = 0; i < a.length; i++) if (a[i] !== b[i]) return false
  return true
}

