 * Resolves a changed region into one of: `mine`, `theirs` or `both`
 * (the two sides made the same change) carrying the resolved lines, or
 * `conflict` carrying mine's, the base's and theirs's lines.
 */
function resolveRegion(base, region) {
  if (region.changes.length === 1) {
    const change = region.changes[0]
    return { kind: change.side, lines: change.lines }
  }

  const mineChanges = region.changes.filter(change => change.side === 'mine')
  const theirsChanges = region.changes.filter(change => change.side === 'theirs')
  const mineLines = buildSideLines(base, region, mineChanges)
  const theirsLines = buildSideLines(base, region, theirsChanges)
  const baseLines = base.slice(region.baseStart, region.baseEnd)

  if (arraysEqual(mineLines, theirsLines)) return { kind: 'both', lines: mineLines }
  if (arraysEqual(mineLines, baseLines)) return { kind: 'theirs', lines: theirsLines }
  if (arraysEqual(theirsLines, baseLines)) return { kind: 'mine', lines: mineLines }
  return { kind: 'conflict', mineLines, baseLines, theirsLines }
}

/**
 * Computes the full three-way merge as an ordered list of regions:
 * `{ kind: 'stable', lines }`, `{ kind: 'mine' | 'theirs' | 'both', lines }`
 * or `{ kind: 'conflict', mineLines, baseLines, theirsLines }`.
 */
export function mergeDocuments(mine, base, theirs) {
  const mineChanges = computeChanges(base, mine, computeMatches(base, mine), 'mine')
  const theirsChanges = computeChanges(base, theirs, computeMatches(base, theirs), 'theirs')
  const allChanges = mergeChangeLists(mineChanges, theirsChanges)
  const regions = buildRegions(base, allChanges)

  return regions.map(region => {
    if (region.kind === 'stable') return { kind: 'stable', lines: base.slice(region.baseStart, region.baseEnd) }
    return resolveRegion(base, region)
  })
}
"}

