 * Turns the merged regions into the output text of each mode, and
 * reports whether any conflict was written.
 */

/**
 * Renders the regions as merged text, with conflict markers around any
 * conflict region. `withBase` controls whether a conflict includes the
 * `||||||| base` section (true for `merge`, false for `merge2`).
 * Returns `{ text, conflicted }`.
 */
export function formatMerge(regions, withBase) {
  const lines = []
  let conflicted = false

  for (const region of regions) {
    if (region.kind !== 'conflict') {
      lines.push(...region.lines)
      continue
    }
    conflicted = true
    lines.push('<<<<<<< mine')
    lines.push(...region.mineLines)
    if (withBase) {
      lines.push('||||||| base')
      lines.push(...region.baseLines)
    }
    lines.push('=======')
    lines.push(...region.theirsLines)
    lines.push('>>>>>>> theirs')
  }

  const text = lines.map(line => `${line}\n`).join('')
  return { text, conflicted }
}

/**
 * Renders one summary line per region: `stable N`, `mine N`, `theirs N`,
 * `both N`, or `conflict mine=A base=O theirs=B`. Returns
 * `{ text, conflicted }`.
 */
export function formatRegions(regions) {
  const lines = []
  let conflicted = false

  for (const region of regions) {
    if (region.kind === 'conflict') {
      conflicted = true
      lines.push(`conflict mine=${region.mineLines.length} base=${region.baseLines.length} theirs=${region.theirsLines.length}`)
    } else {
      lines.push(`${region.kind} ${region.lines.length}`)
    }
  }

  const text = lines.map(line => `${line}\n`).join('')
  return { text, conflicted }
}
"}

