 * Turns a configuration document's lines into the document tree defined in
 * ./model.js, applying the table-header and key/value grammar line by line.
 */

import { LineParser, parseDottedName, parseValue, assignDotted } from './line-parser.js'
import { makeTable, pathToString } from './model.js'

/** Splits input on newlines, dropping the empty tail a trailing newline leaves. */
export function splitLines(input) {
  const lines = input.split('\n')
  if (lines.length > 0 && lines[lines.length - 1] === '') lines.pop()
  return lines
}

function walkIntoTable(node, name, path, p) {
  path.push(name)
  const child = node.map.get(name)
  if (child === undefined) {
    const t = makeTable()
    node.map.set(name, t)
    return t
  }
  if (child.kind === 'table') return child
  if (child.kind === 'aot') {
    path.push({ index: child.items.length - 1 })
    return child.items[child.items.length - 1]
  }
  p.err(pathToString(path) + ' is not a table')
}

function processHeader(state, p) {
  p.i++ // consume the first '['
  let isArray = false
  if (!p.eof() && p.peek() === '[') {
    isArray = true
    p.i++
  }
  p.skipSpaces()
  const parts = parseDottedName(p)
  p.skipSpaces()

  if (p.eof() || p.peek() !== ']') p.err('unterminated table header')
  p.i++
  if (isArray) {
    if (p.eof() || p.peek() !== ']') p.err('unterminated table header')
    p.i++
  }

  p.skipBoundary()
  if (!p.eof()) p.err('trailing text after a table header')

  let node = state.root
  const path = []
  for (let idx = 0; idx < parts.length - 1; idx++) {
    node = walkIntoTable(node, parts[idx], path, p)
  }
  const lastName = parts[parts.length - 1]
  path.push(lastName)
  const existing = node.map.get(lastName)

  if (isArray) {
    let aot
    if (existing === undefined) {
      aot = { kind: 'aot', items: [] }
      node.map.set(lastName, aot)
    } else if (existing.kind === 'aot') {
      aot = existing
    } else {
      p.err(pathToString(path) + ' is not an array of tables')
    }
    const fresh = makeTable()
    aot.items.push(fresh)
    state.current = fresh
    state.currentPath = path.concat([{ index: aot.items.length - 1 }])
  } else {
    let table
    if (existing === undefined) {
      table = makeTable()
      node.map.set(lastName, table)
    } else if (existing.kind === 'table') {
      table = existing
    } else {
      p.err(pathToString(path) + ' is not a table')
    }
    if (table.headerOpened) {
      p.err('table ' + pathToString(path) + ' is defined twice')
    }
    table.headerOpened = true
    state.current = table
    state.currentPath = path
  }
