function sortedKeys(map) {
  return Array.from(map.keys()).sort()
}

function renderJSON(node, depth) {
  const pad = '  '.repeat(depth)
  const padChild = '  '.repeat(depth + 1)
  if (node.kind === 'table') {
    const keys = sortedKeys(node.map)
    if (keys.length === 0) return '{}'
    const lines = keys.map(
      (k) => padChild + JSON.stringify(k) + ': ' + renderJSON(node.map.get(k), depth + 1)
    )
    return '{\n' + lines.join(',\n') + '\n' + pad + '}'
  }
  if (node.kind === 'aot' || node.kind === 'array') {
    if (node.items.length === 0) return '[]'
    const lines = node.items.map((item) => padChild + renderJSON(item, depth + 1))
    return '[\n' + lines.join(',\n') + '\n' + pad + ']'
  }
  // string, integer, float, boolean
  return JSON.stringify(node.value)
}

/** Prints the document as JSON indented by two spaces, with a trailing newline. */
export function printJSON(root) {
  return renderJSON(root, 0) + '\n'
}

function typeName(node) {
  if (node.kind === 'table') return 'table'
  if (node.kind === 'aot' || node.kind === 'array') return 'array'
  return node.kind
}

function joinKey(path, key) {
  return path ? path + '.' + key : key
}

function joinIndex(path, index) {
  return path + '[' + index + ']'
}

function walkKeys(node, path, out) {
  if (path !== '') out.push(path + ' ' + typeName(node))
  if (node.kind === 'table') {
    for (const key of sortedKeys(node.map)) {
      walkKeys(node.map.get(key), joinKey(path, key), out)
    }
  } else if (node.kind === 'aot' || node.kind === 'array') {
    node.items.forEach((item, index) => walkKeys(item, joinIndex(path, index), out))
  }
}

/** Prints one `<path> <type>` line per node below the root, depth first. */
export function printKeys(root) {
  const out = []
  walkKeys(root, '', out)
  return out.length === 0 ? '' : out.join('\n') + '\n'
}
"}

