      cursor.pos++
      const esc = cursor.line[cursor.pos]
      if (esc === undefined) throw new ParseError(lineNo, 'unterminated string')
      switch (esc) {
        case '"':
          text += '"'
          cursor.pos++
          break
        case '\\':
          text += '\\'
          cursor.pos++
          break
        case 'n':
          text += '\n'
          cursor.pos++
          break
        case 't':
          text += '\t'
          cursor.pos++
          break
        case 'r':
          text += '\r'
          cursor.pos++
          break
        case '0':
          text += '\0'
          cursor.pos++
          break
        case 'u': {
          const hex = cursor.line.slice(cursor.pos + 1, cursor.pos + 5)
