 * Parses a configuration document (as described in the task prompt) into a
 * tree of `TableNode` / `ArrayNode` / scalar records rooted at a `TableNode`.
 */
import { ParseError } from './errors.js'
import { TableNode, ArrayNode, scalar } from './model.js'
import { Cursor, parseName, parseDottedName, parseBareToken, parseQuotedString } from './lexer.js'

function pathStr(names) {
  return names.join('.')
}

/** True when the line contributes nothing: blank, or a comment line. */
function isSkippableLine(line) {
  let i = 0
  while (line[i] === ' ' || line[i] === '\t') i++
  const ch = line[i]
  return ch === undefined || ch === '#' || ch === ';'
}

/**
 * Resolves a value found while walking a dotted path so the walk can
 * continue through it: a table is used directly, an array of tables uses
 * its last element, and anything else is an error.
 */
function resolveIntermediate(node, pathSoFar, lineNo) {
  if (node instanceof TableNode) return node
  if (node instanceof ArrayNode && node.isArrayOfTables) return node.items[node.items.length - 1]
  throw new ParseError(lineNo, `${pathStr(pathSoFar)} is not a table`)
}

/**
 * Walks `names` from `table`, creating tables along the way as needed, and
 * returns the table reached. `pathPrefix` is the absolute path to `table`,
 * used to build error messages.
 */
function walkIntermediates(table, names, pathPrefix, lineNo) {
  let node = table
  const pathAcc = pathPrefix.slice()
  for (const name of names) {
    pathAcc.push(name)
    const existing = node.entries.get(name)
    if (existing === undefined) {
      const t = new TableNode()
      node.entries.set(name, t)
      node = t
    } else {
      node = resolveIntermediate(existing, pathAcc, lineNo)
    }
  }
  return node
}

/** Assigns `value` at `names` (relative to `table`), whose absolute path is `pathPrefix.concat(names)`. */
function assignKey(table, pathPrefix, names, value, lineNo) {
  const intermediateNames = names.slice(0, -1)
  const leafName = names[names.length - 1]
  const parent = walkIntermediates(table, intermediateNames, pathPrefix, lineNo)
  if (parent.entries.has(leafName)) {
    throw new ParseError(lineNo, `key ${pathStr(pathPrefix.concat(names))} is defined twice`)
  }
  parent.entries.set(leafName, value)
}

// ---- values ----

function parseValue(cursor, absolutePath, lineNo) {
  cursor.skipWs()
  const ch = cursor.line[cursor.pos]
  if (cursor.atLineEnd() || ch === ',' || ch === ']' || ch === '}') {
    throw new ParseError(lineNo, 'expected a value')
  }
  if (ch === '"' || ch === "'") return scalar('string', parseQuotedString(cursor, lineNo))
  if (ch === '[') return parseArray(cursor, absolutePath, lineNo)
  if (ch === '{') return parseInlineTable(cursor, absolutePath, lineNo)
  const { type, value } = parseBareToken(cursor, lineNo)
  return scalar(type, value)
}

function parseArray(cursor, absolutePath, lineNo) {
  cursor.pos++ // '['
  cursor.skipWs()
  const items = []
  if (cursor.atLineEnd()) throw new ParseError(lineNo, 'unterminated array')
  if (cursor.line[cursor.pos] === ']') {
    cursor.pos++
    return new ArrayNode(false)
  }
  for (;;) {
    items.push(parseValue(cursor, absolutePath, lineNo))
    cursor.skipWs()
    if (cursor.atLineEnd()) throw new ParseError(lineNo, 'unterminated array')
    const ch = cursor.line[cursor.pos]
    if (ch === ',') {
      cursor.pos++
      cursor.skipWs()
      if (cursor.atLineEnd()) throw new ParseError(lineNo, 'unterminated array')
      if (cursor.line[cursor.pos] === ']') {
        cursor.pos++
        break
      }
      continue
    }
    if (ch === ']') {
      cursor.pos++
      break
    }
    throw new ParseError(lineNo, 'unterminated array')
  }
  const node = new ArrayNode(false)
  node.items = items
  return node
}

function parseInlineTable(cursor, absolutePath, lineNo) {
  cursor.pos++ // '{'
  cursor.skipWs()
  const table = new TableNode()
  if (cursor.atLineEnd()) throw new ParseError(lineNo, 'unterminated inline table')
  if (cursor.line[cursor.pos] === '}') {
    cursor.pos++
    return table
