  for (;;) {
    cursor.skipWs()
    const names = parseDottedName(cursor, lineNo)
    cursor.skipWs()
    if (cursor.atLineEnd() || cursor.line[cursor.pos] !== '=') {
      throw new ParseError(lineNo, 'expected = in an inline table')
    }
    cursor.pos++
    cursor.skipWs()
    const value = parseValue(cursor, absolutePath.concat(names), lineNo)
    assignKey(table, absolutePath, names, value, lineNo)
    cursor.skipWs()
    if (cursor.atLineEnd()) throw new ParseError(lineNo, 'unterminated inline table')
    const ch = cursor.line[cursor.pos]
    if (ch === ',') {
      cursor.pos++
      continue
    }
    if (ch === '}') {
      cursor.pos++
      break
    }
    throw new ParseError(lineNo, 'unterminated inline table')
  }
  return table
}

// ---- headers ----

function parseHeader(cursor, lineNo) {
  cursor.pos++ // '['
  let isArrayHeader = false
  if (cursor.line[cursor.pos] === '[') {
    isArrayHeader = true
    cursor.pos++
  }
  const names = parseDottedName(cursor, lineNo)
  cursor.skipWs()
  if (cursor.atLineEnd() || cursor.line[cursor.pos] !== ']') {
    throw new ParseError(lineNo, 'unterminated table header')
  }
  cursor.pos++
  if (isArrayHeader) {
    if (cursor.atLineEnd() || cursor.line[cursor.pos] !== ']') {
      throw new ParseError(lineNo, 'unterminated table header')
    }
    cursor.pos++
  }
  cursor.skipWs()
  if (!cursor.atLineEnd()) throw new ParseError(lineNo, 'trailing text after a table header')
  return { names, isArrayHeader }
}

function enterTableHeader(root, names, lineNo) {
  const intermediateNames = names.slice(0, -1)
  const leafName = names[names.length - 1]
  const parent = walkIntermediates(root, intermediateNames, [], lineNo)
  const existing = parent.entries.get(leafName)
  if (existing === undefined) {
    const t = new TableNode()
    t.headerMadeCurrent = true
    parent.entries.set(leafName, t)
    return t
  }
  if (!(existing instanceof TableNode)) {
    throw new ParseError(lineNo, `${pathStr(names)} is not a table`)
  }
  if (existing.headerMadeCurrent) {
    throw new ParseError(lineNo, `table ${pathStr(names)} is defined twice`)
  }
  existing.headerMadeCurrent = true
  return existing
}

function enterArrayTableHeader(root, names, lineNo) {
  const intermediateNames = names.slice(0, -1)
  const leafName = names[names.length - 1]
  const parent = walkIntermediates(root, intermediateNames, [], lineNo)
  const existing = parent.entries.get(leafName)
  let arr
  if (existing === undefined) {
    arr = new ArrayNode(true)
    parent.entries.set(leafName, arr)
  } else {
    if (!(existing instanceof ArrayNode) || !existing.isArrayOfTables) {
      throw new ParseError(lineNo, `${pathStr(names)} is not an array of tables`)
    }
    arr = existing
  }
  const t = new TableNode()
  arr.items.push(t)
  return t
}

