/** Thrown when a component holds a `%` not followed by two hex digits. */
export class PercentError extends Error {
  constructor(component) {
    super(`the ${component} has a truncated percent-encoding`)
    this.component = component
  }
}

const DEFAULT_PORTS = { http: '80', ws: '80', https: '443', wss: '443', ftp: '21' }

function isHexDigit(ch) {
  return ch !== undefined && /^[0-9a-fA-F]$/.test(ch)
}

function isUnreservedCode(code) {
  return (
    (code >= 65 && code <= 90) || // A-Z
    (code >= 97 && code <= 122) || // a-z
    (code >= 48 && code <= 57) || // 0-9
    code === 45 || // -
    code === 46 || // .
    code === 95 || // _
    code === 126 // ~
  )
}

function asciiLower(str) {
  let out = ''
  for (const ch of str) {
    const code = ch.charCodeAt(0)
    out += code >= 65 && code <= 90 ? String.fromCharCode(code + 32) : ch
  }
  return out
