    const c = rest[i]
    if (c === '/' || c === '?' || c === '#') break
    if (c === ':') {
      scheme = rest.slice(0, i)
      rest = rest.slice(i + 1)
      break
    }
  }

  let authority
  if (rest.startsWith('//')) {
    rest = rest.slice(2)
    let end = rest.length
    for (let i = 0; i < rest.length; i++) {
      if (rest[i] === '/' || rest[i] === '?' || rest[i] === '#') {
        end = i
        break
      }
    }
    authority = rest.slice(0, end)
    rest = rest.slice(end)
  }

  let pathEnd = rest.length
  for (let i = 0; i < rest.length; i++) {
    if (rest[i] === '?' || rest[i] === '#') {
      pathEnd = i
      break
    }
  }
  const path = rest.slice(0, pathEnd)
