/**
 * The command. `node src/cli.js normalize` normalizes one URI reference per
 * input line; `node src/cli.js resolve` resolves the reference on each line
 * against the base that precedes it. Both print one result per line.
 */

import { readFileSync } from 'node:fs'
import { parseReference, normalize, resolve, PercentError } from './uri.js'

/** Raised for a per-line failure; carries the exact message to print. */
class LineError extends Error {}

function splitLines(input) {
  if (input === '') return []
  const lines = input.split('\n')
  if (input.endsWith('\n')) lines.pop()
  return lines
}

function processNormalize(line) {
  return normalize(parseReference(line))
}

function processResolve(line) {
  const spaceIdx = line.indexOf(' ')
  if (spaceIdx === -1) throw new LineError('expected a base and a reference')
  const baseStr = line.slice(0, spaceIdx)
  const refStr = line.slice(spaceIdx + 1)

  const base = parseReference(baseStr)
  if (base.scheme === undefined) throw new LineError('the base has no scheme')
  const ref = parseReference(refStr)

  return normalize(resolve(base, ref))
}

function main() {
  const args = process.argv.slice(2)
  if (args.length !== 1 || (args[0] !== 'normalize' && args[0] !== 'resolve')) {
    process.stderr.write('error: usage: cli.js normalize|resolve\n')
    process.exit(2)
  }
  const mode = args[0]
  const process_ = mode === 'normalize' ? processNormalize : processResolve

  const input = readFileSync(0, 'utf8')
  const lines = splitLines(input)

  const outputs = []
  for (let i = 0; i < lines.length; i++) {
    const lineNumber = i + 1
    try {
      outputs.push(process_(lines[i]))
    } catch (err) {
      if (err instanceof PercentError) {
        process.stderr.write(`error: line ${lineNumber}: ${err.message}\n`)
      } else if (err instanceof LineError) {
        process.stderr.write(`error: line ${lineNumber}: ${err.message}\n`)
      } else {
        throw err
      }
      process.exit(2)
    }
  }

  process.stdout.write(outputs.length > 0 ? outputs.join('\n') + '\n' : '')
  process.exit(0)
}

main()
"}

