 * The two policy kinds a limiter file can declare, each keeping one
 * independent state per key. Amounts that must stay exact under fractional
 * accumulation or arbitrarily large counts are kept as BigInt.
 */

/**
 * A token bucket: holds `capacity` tokens, refills `refill` tokens for every
 * `per` ticks that pass, and allows a request when it holds at least one
 * whole token. Internally tokens are tracked scaled by `per` so that partial
 * periods accumulate exactly, with no rounding.
 */
export class TokenBucket {
  constructor(capacity, refill, per) {
    this.capacity = capacity
    this.refill = refill
    this.per = per
    this.capacityScaled = capacity * per
    this.states = new Map()
  }

  #stateFor(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { tokensScaled: this.capacityScaled, lastTick: null }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key)
    if (state.lastTick === null) {
      state.lastTick = tick
      return
    }
    if (tick > state.lastTick) {
      const delta = tick - state.lastTick
      const gained = this.refill * delta
      const next = state.tokensScaled + gained
      state.tokensScaled = next > this.capacityScaled ? this.capacityScaled : next
      state.lastTick = tick
    }
  }

  allow(key) {
    const state = this.#stateFor(key)
    return state.tokensScaled >= this.per
  }

  record(key) {
    const state = this.#stateFor(key)
    state.tokensScaled -= this.per
  }
}

/**
 * A sliding window: remembers the ticks it recorded for a key, forgetting
 * any at or before `tick - span` on each advance, and allows a request when
 * fewer than `limit` ticks remain remembered.
 */
export class SlidingWindow {
  constructor(limit, span) {
    this.limit = limit
    this.span = span
    this.states = new Map()
  }

  #stateFor(key) {
    let state = this.states.get(key)
    if (state === undefined) {
      state = { ticks: [] }
      this.states.set(key, state)
    }
    return state
  }

  advance(key, tick) {
    const state = this.#stateFor(key)
    const cutoff = tick - this.span
    let start = 0
    while (start < state.ticks.length && state.ticks[start] <= cutoff) start++
    if (start > 0) state.ticks.splice(0, start)
  }

  allow(key) {
    const state = this.#stateFor(key)
    return BigInt(state.ticks.length) < this.limit
  }

  record(key) {
    const state = this.#stateFor(key)
    state.ticks.push(this.lastRecordedTick)
  }
}
"}

