{"file_path":"/home/user/deepseek-harness/.proving-ground/runs/h3-baseline-sonnet-t5-20260925T221232Z/cell-x1q8mp/src/simulate.js","content":"/**
 * Replays a parsed limiter file's events against its policies, producing
 * one verdict per event in file order.
 */

/**
 * Finds the route whose prefix is a prefix of `key` and is longest among
 * those that match, or `undefined` when no route matches.
 */
function matchRoute(routes, key) {
  let best
  for (const route of routes) {
    if (key.startsWith(route.prefix)) {
      if (best === undefined || route.prefix.length > best.prefix.length) best = route
    }
  }
  return best
}

/**
 * Runs every event against its route's policies and returns
 * `{ verdicts, perKey, total }`, where `verdicts` is an array of
 * `{ tick, key, allowed, deniedBy }` in file order, `perKey` maps each key
 * that saw an event to `{ allowed, denied }`, and `total` is the same shape
 * summed across all keys.
 */
export function simulate({ policies, routes, events }) {
  const verdicts = []
  const perKey = new Map()
  const total = { allowed: 0, denied: 0 }

  for (const { tick, key } of events) {
    const route = matchRoute(routes, key)
    let allowed = true
    let deniedBy = null

    if (route !== undefined) {
      const routePolicies = route.policyNames.map((name) => policies.get(name))
      for (const policy of routePolicies) policy.advance(key, tick)
      for (let i = 0; i < routePolicies.length; i++) {
        if (!routePolicies[i].allow(key)) {
          allowed = false
          deniedBy = route.policyNames[i]
          break
        }
      }
      if (allowed) {
        for (const policy of routePolicies) policy.record(key, tick)
      }
    }

    verdicts.push({ tick, key, allowed, deniedBy })

    let counts = perKey.get(key)
    if (counts === undefined) {
      counts = { allowed: 0, denied: 0 }
      perKey.set(key, counts)
    }
    if (allowed) {
      counts.allowed++
      total.allowed++
    } else {
      counts.denied++
      total.denied++
    }
  }

  return { verdicts, perKey, total }
}
"}

